{{--
    THE GIFT OFFER'S ROW -- design R2 "Cream chips" (Lane GO; docs/plans/
    gift-offers/exit-popup-designs.html, R2 in R6's cream and gold, 93px):
    the claimed gift's photo and name, Free / Full size / ×N chips (×1 unless the item gives more, Lane GQ), "Complete
    your order in" above a large clock, a thin grey border with a pink line
    that shrinks as the time runs. Only the clock and the line move.

    Drawn just below the free gifts box in the cart panel, on the cart page
    and in the checkout summary, from GiftOffers::row(): $goRow when the
    basket holds a live claim, $goEnded ("This gift has ended.") when an
    ended claim link was opened, and otherwise NOTHING -- not a byte, so every
    page without a gift is exactly what it was (StorefrontEnglishUnchangedTest).

    The clock: one small inline script, printed only with a row, run once per
    page (window.kbbGoT), one 1-second timer that stops at zero and while no
    row is left. It sets text and a stroke offset -- nothing is measured. At
    zero the row says the gift has left; the server stops drawing it and
    Place order leaves it out. No request.
--}}@if (! empty($goRow))<style>.kgo-r{position:relative;display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:11px;align-items:center;box-sizing:border-box;min-height:93px;margin:10px 0;padding:19px 12px 19px 9px;border:1px solid #ddd6d9;border-radius:14px;background:#fffaf2;color:#2a2228;font-size:12.5px;line-height:1.3;text-align:start}.kgo-loop{position:absolute;left:-1px;top:-1px;width:calc(100% + 2px);height:calc(100% + 2px);overflow:visible;pointer-events:none}.kgo-loop rect{fill:none;stroke:#c6395f;stroke-width:2.5;stroke-dasharray:100 100;transition:stroke-dashoffset 1s linear}.kgo-im{display:block;box-sizing:border-box;width:44px;height:44px;border-radius:10px;overflow:hidden;background:#fff;border:1px solid #f1e4cc}.kgo-im img{display:block;width:100%;height:100%;object-fit:contain}.kgo-nm{min-width:0;display:grid;gap:3px}.kgo-nm b{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;font-size:13px;font-weight:800;line-height:1.25}.kgo-meta{display:flex;gap:4px;flex-wrap:nowrap}.kgo-meta i{font-style:normal;font-size:10px;font-weight:800;border-radius:6px;padding:1px 6px;background:#fbf1de;color:#8a6a2c;white-space:nowrap}.kgo-meta i.g{background:#8a6a2c;color:#fffaf2}.kgo-below{color:#a12d4f;font-size:11px;font-weight:700}.kgo-tm{display:grid;justify-items:end;gap:1px;text-align:end}.kgo-r{container-type:inline-size}@container (max-width:330px){.kgo-r>.kgo-nm{grid-column:2/-1}.kgo-r>.kgo-tm{grid-column:2/-1;grid-row:2;justify-items:start;text-align:start;gap:3px}}.kgo-tm small{font-size:9.5px;font-weight:600;color:#8a6a2c;white-space:nowrap}.kgo-tw{display:inline-flex;align-items:center;gap:5px;padding:5px 9px 5px 7px;border-radius:9px;background:#2a2228;color:#fff;direction:ltr}.kgo-tw svg{flex:none;width:15px;height:15px}.kgo-tw .kgo-hd{transform-origin:12px 13px;animation:kgohd 4s steps(8) infinite}@keyframes kgohd{to{transform:rotate(360deg)}}@media (prefers-reduced-motion:reduce){.kgo-tw .kgo-hd{animation:none}}.kgo-clk{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;font-weight:700;font-size:16px;line-height:1;letter-spacing:.04em}.kgo-r.low .kgo-tw{background:#d1213f}.kgo-end{margin:10px 0;padding:10px 12px;border:1px solid #ddd6d9;border-radius:14px;background:#fffaf2;color:#8a6a2c;font-size:12.5px;font-weight:700;line-height:1.4}</style><div class="kgo-r" data-kgo-row data-left="{{ $goRow['left'] }}" data-total="{{ $goRow['total'] }}" data-over="{{ $goRow['over'] }}"><svg class="kgo-loop" aria-hidden="true" focusable="false"><rect x="0" y="0" width="100%" height="100%" rx="14" ry="14" pathLength="100" style="stroke-dashoffset:{{ number_format(100 * (1 - $goRow['left'] / max(1, $goRow['total'])), 2, '.', '') }}"/></svg><span class="kgo-im">@if ($goRow['img'] !== '')<img src="{{ $goRow['img'] }}" alt="" width="44" height="44" loading="lazy" decoding="async">@endif</span><span class="kgo-nm"><b>{{ $goRow['name'] }}</b><span class="kgo-meta"><i class="g">{{ $goRow['free'] }}</i><i>{{ $goRow['full'] }}</i><i>×{{ $goRow['qty'] ?? 1 }}</i></span>@if ($goRow['below'] !== '')<small class="kgo-below">{{ $goRow['below'] }}</small>@endif</span><span class="kgo-tm"><small>{{ $goRow['label'] }}</small><span class="kgo-tw" role="timer"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="13" r="8"/><path d="M10 2h4M12 2v3M19 6l-1.5 1.5"/><path class="kgo-hd" d="M12 13V9"/></svg><span class="kgo-clk">{{ $goRow['left'] >= 3600 ? sprintf('%d:%02d:%02d', intdiv($goRow['left'], 3600), intdiv($goRow['left'] % 3600, 60), $goRow['left'] % 60) : sprintf('%02d:%02d', intdiv($goRow['left'], 60), $goRow['left'] % 60) }}</span></span></span><script>(function(w,d){if(w.kbbGoT)return;w.kbbGoT=1;function f(s){var h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;return(h?h+':':'')+(m<10?'0':'')+m+':'+(x<10?'0':'')+x}var iv=setInterval(function(){var rows=d.querySelectorAll('[data-kgo-row]'),live=0;for(var i=0;i<rows.length;i++){var r=rows[i];if(!r.kgoEnd)r.kgoEnd=Date.now()+(+r.getAttribute('data-left'))*1000;var s=Math.max(0,Math.round((r.kgoEnd-Date.now())/1000)),T=+r.getAttribute('data-total')||1,c=r.querySelector('.kgo-clk'),q=r.querySelector('rect');if(c)c.textContent=f(s);if(q)q.style.strokeDashoffset=(100*(1-s/T)).toFixed(2);r.classList.toggle('low',s<=120);if(s<=0){r.removeAttribute('data-kgo-row');r.className='kgo-end';r.textContent=r.getAttribute('data-over')}else live++}if(!live)clearInterval(iv)},1000)})(window,document)</script></div>@elseif (! empty($goEnded))<div class="kgo-end" role="status" style="margin:10px 0;padding:10px 12px;border:1px solid #ddd6d9;border-radius:14px;background:#fffaf2;color:#8a6a2c;font-size:12.5px;font-weight:700">{{ $goEnded }}</div>@endif
